SELECT Name
FROM dbo.Products
WHERE Price > (SELECT AVG(Price) FROM dbo.Products);

SELECT c.Name
FROM dbo.Customers c
WHERE EXISTS (SELECT 1 FROM dbo.Orders o WHERE o.CustomerId = c.Id);

WITH BigOrders AS (
  SELECT * FROM dbo.Orders WHERE Total > 1000)
SELECT * FROM BigOrders WHERE Status = 'Open';

SELECT c.Name,
  (SELECT COUNT(*) FROM dbo.Orders o WHERE o.CustomerId = c.Id) AS OrderCount
FROM dbo.Customers c;
